178	  test("retire scenario 2", { tag: '@functionality' }, async ({ browser }) => {
179	    const sheet = ui.sheetId();
180	    const pg_uma = await ui.userPage(browser, "uma", sheet);
181	    await ui.setToday(pg_uma, "2026-04-05");
182	    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
183	    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
184	    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-10"})).toBe(true);
185	    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
186	    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
187	    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
188	    const c_cam_0 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "12.50", "date": "2026-03-20"}));
189	    expect(await ui.claimCount(pg_uma, p_cam)).toBe(1);
190	    expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
191	    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "B"})).toBe(true);
192	    const c_cam_1 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "date": "2026-03-20"}));
193	    expect(await ui.retire(pg_uma, p_ben, "2026-02-25")).toBe(true);
194	    expect(await ui.claimAction(pg_uma, c_cam_1, "void")).toBe(true);
195	    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
196	    await ui.refresh(pg_uma);
197	    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
198	    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
199	    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
200	    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
201	    await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.02");
202	    await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("VOID");
