      on <span data-testid="person-statement-date">{person.statementDate ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          take.mutate();
        }}
      >
        Statement
      </button>
      {error && (
        <p data-testid="person-error" role="alert">
